import itertools
import math


def minimum_tour(costs, start=0):
    if not isinstance(costs, list) or len(costs) > 9:
        raise ValueError("costs must be a list with at most nine rows")
    size = len(costs)
    if size == 0:
        if start != 0:
            raise ValueError("invalid start")
        return [], 0.0
    if isinstance(start, bool) or not isinstance(start, int) or not 0 <= start < size:
        raise ValueError("invalid start")
    if any(not isinstance(row, list) or len(row) != size for row in costs):
        raise ValueError("costs must be square")
    if any(
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(value)
        or value < 0
        for row in costs
        for value in row
    ):
        raise ValueError("invalid cost")
    if size == 1:
        return [start, start], 0.0

    others = [index for index in range(size) if index != start]
    best_route = None
    best_total = None
    for permutation in itertools.permutations(others):
        route = (start,) + permutation
        total = sum(costs[route[index]][route[index + 1]] for index in range(size - 1))
        closed_route = route + (start,)
        if best_total is None or total < best_total or (
            total == best_total and closed_route < best_route
        ):
            best_total = total
            best_route = closed_route
    return list(best_route), float(best_total)

